from __future__ import annotations
import math
from dataclasses import dataclass

@dataclass(frozen=True)
class Metrics:
    n: int
    states: int
    bits: float
    depth: int
    work_over_kT: float

def metrics(n: int) -> Metrics:
    if n < 0:
        raise ValueError("n must be nonnegative")
    states = math.factorial(n)
    logf = math.lgamma(n + 1.0)
    return Metrics(n, states, logf / math.log(2.0), (states - 1).bit_length(), logf)

if __name__ == "__main__":
    for n in range(11):
        print(metrics(n))

from __future__ import annotations
import math

def audit_history(n: int, available_states: int) -> dict[str, int | float | bool]:
    if n < 0 or available_states < 1:
        raise ValueError("Require n >= 0 and available_states >= 1")
    required = math.factorial(n)
    deficit = max(0.0, math.lgamma(n + 1) / math.log(2) - math.log2(available_states))
    return {"required": required, "available": available_states,
            "passes_capacity_test": available_states >= required,
            "missing_states": max(0, required - available_states),
            "bit_deficit": deficit}

if __name__ == "__main__":
    for states in (100, 1000, math.factorial(8)):
        print(audit_history(8, states))

from __future__ import annotations
import math

def padding_experiment(n: int, base_height: int, max_padding: int) -> list[tuple[int, int, float]]:
    if min(n, base_height, max_padding) < 0:
        raise ValueError("inputs must be nonnegative")
    fixed_bits = math.lgamma(n + 1) / math.log(2)
    return [(r, base_height + r, fixed_bits) for r in range(max_padding + 1)]

if __name__ == "__main__":
    n = 8
    minimum = (math.factorial(n) - 1).bit_length()
    for row in padding_experiment(n, minimum, 8):
        print(f"padding={row[0]:2d}, height={row[1]:2d}, erased_bits={row[2]:.6f}")

