from __future__ import annotations
import math

def factorial_information(n: int) -> tuple[float, float, int]:
    """Return (bits erased, W/(kT), exact binary depth lower bound)."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    logf = math.lgamma(n + 1.0)
    factorial = math.factorial(n)
    return logf / math.log(2.0), logf, (factorial - 1).bit_length()

from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class TreeSummary:
    leaves: int
    height: int

def redundant_pad(tree: TreeSummary, levels: int) -> TreeSummary:
    """Duplicate the tree below each of the requested redundant levels."""
    if levels < 0 or tree.leaves < 1 or tree.height < 0:
        raise ValueError("invalid tree summary or padding")
    return TreeSummary(tree.leaves * (2 ** levels), tree.height + levels)

